using System.Buffers;
using System.Security.Cryptography;
using System.Text;
using KidsfitCRM.Api.Common;

namespace KidsfitCRM.Api.Infrastructure;

/// <summary>Private evidence files. Storage keys are generated by this service and never come from clients.</summary>
public interface IFileStorageService
{
    Task<StoredFile> SaveAsync(Stream source, string kind, CancellationToken cancellationToken);
    Stream OpenRead(string storageKey);
    void Delete(string storageKey);
}

public sealed record StoredFile(string StorageKey, long FileSize, string Sha256, string MimeType);

public sealed class LocalFileStorageService : IFileStorageService
{
    public const int MaxFileBytes = 5 * 1024 * 1024;
    private static readonly Dictionary<string, string> Folders = new(StringComparer.Ordinal)
    {
        ["CONTRACT"] = "contracts",
        ["RENEWAL"] = "renewals",
        ["RECEIPT"] = "receipts",
        ["PAYOUT"] = "payouts",
    };
    private readonly string root;

    public LocalFileStorageService(IConfiguration configuration, IHostEnvironment environment)
    {
        var configured = configuration["Storage:RootPath"];
        var fallback = environment.IsDevelopment()
            ? Path.Combine(environment.ContentRootPath, "Storage")
            : OperatingSystem.IsWindows()
                ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "KidsfitCRM", "Storage")
                : "/var/lib/kidsfit-crm/storage";
        root = Path.GetFullPath(string.IsNullOrWhiteSpace(configured) ? fallback : configured);
        if (root.Contains(Path.DirectorySeparatorChar + "wwwroot" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)
            || Path.GetFileName(root).Equals("wwwroot", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("Private storage cannot be configured inside wwwroot.");
        Directory.CreateDirectory(root);
    }

    public async Task<StoredFile> SaveAsync(Stream source, string kind, CancellationToken cancellationToken)
    {
        if (!Folders.TryGetValue(kind, out var folder))
            throw ApiValidationException.For("kind", "Loại chứng từ không hợp lệ.");
        var storageKey = folder + "/" + Guid.NewGuid().ToString("N");
        var path = Resolve(storageKey);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var buffer = ArrayPool<byte>.Shared.Rent(81920);
        try
        {
            long length = 0;
            var signature = new byte[16];
            var firstBytes = 0;
            using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
            await using (var file = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, FileOptions.Asynchronous))
            {
                int count;
                while ((count = await source.ReadAsync(buffer.AsMemory(), cancellationToken)) > 0)
                {
                    length += count;
                    if (length > MaxFileBytes)
                        throw ApiValidationException.For("file", "Tệp phải có dung lượng từ 1 byte đến 5 MB.");
                    if (firstBytes < signature.Length)
                    {
                        var take = Math.Min(count, signature.Length - firstBytes);
                        buffer.AsSpan(0, take).CopyTo(signature.AsSpan(firstBytes));
                        firstBytes += take;
                    }
                    hash.AppendData(buffer, 0, count);
                    await file.WriteAsync(buffer.AsMemory(0, count), cancellationToken);
                }
                await file.FlushAsync(cancellationToken);
            }
            if (length == 0)
                throw ApiValidationException.For("file", "Tệp phải có dung lượng từ 1 byte đến 5 MB.");
            var mime = DetectMime(signature);
            if (mime is null || (mime == "application/pdf" && kind is not ("CONTRACT" or "RENEWAL")))
                throw ApiValidationException.For("file", kind is "CONTRACT" or "RENEWAL"
                    ? "Hợp đồng phải là PDF hoặc ảnh JPG/PNG/WEBP hợp lệ."
                    : "Chứng từ chuyển khoản phải là ảnh JPG/PNG/WEBP hợp lệ.");
            return new StoredFile(storageKey, length, Convert.ToHexString(hash.GetHashAndReset()), mime);
        }
        catch
        {
            File.Delete(path);
            throw;
        }
        finally
        {
            ArrayPool<byte>.Shared.Return(buffer);
        }
    }

    private static string? DetectMime(ReadOnlySpan<byte> bytes)
    {
        if (bytes.Length >= 3 && bytes[0] == 0xFF && bytes[1] == 0xD8 && bytes[2] == 0xFF) return "image/jpeg";
        if (bytes.Length >= 8 && bytes[..8].SequenceEqual(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 })) return "image/png";
        if (bytes.Length >= 12 && Encoding.ASCII.GetString(bytes[..4]) == "RIFF"
            && Encoding.ASCII.GetString(bytes.Slice(8, 4)) == "WEBP") return "image/webp";
        if (bytes.Length >= 5 && Encoding.ASCII.GetString(bytes[..5]) == "%PDF-") return "application/pdf";
        return null;
    }

    public Stream OpenRead(string storageKey) =>
        new FileStream(Resolve(storageKey), FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete, 81920, FileOptions.Asynchronous | FileOptions.SequentialScan);

    public void Delete(string storageKey)
    {
        if (!string.IsNullOrEmpty(storageKey)) File.Delete(Resolve(storageKey));
    }

    private string Resolve(string storageKey)
    {
        var segments = storageKey.Split('/');
        if (segments.Length != 2 || !Folders.Values.Contains(segments[0], StringComparer.Ordinal)
            || segments[1].Length != 32 || !Guid.TryParseExact(segments[1], "N", out _))
            throw new InvalidOperationException("Invalid private storage key.");
        return Path.Combine(root, segments[0], segments[1]);
    }
}
